const datei = new URL('../source/gmc_schaufenster.mjs', import.meta.url);
const quelle = fs.readFileSync(datei, 'utf8');
const anfang = quelle.indexOf('async function holeToken() {');
const ende = quelle.indexOf('\nconst TOKEN = await holeToken();', anfang);
assert.ok(anfang >= 0 && ende > anfang);
const originalFunktion = quelle.slice(anfang, ende);
